<?php declare(strict_types=1);$taxSaved=isset($taxPreview['document']); ?>
<section class="card" id="tax-preview" data-tax-preview>
<?php if($taxSaved): ?><p class="notice"><strong><?= e($taxText('Gespeicherter Vorbereitungsstand')) ?></strong> · <?= e($taxPreview['saved_at']) ?><?=e($taxText('. Die Zahlen stammen aus diesem gespeicherten Stand.'))?></p><div class="actions"><a class="btn btn-solid theme-primary button" href="<?= e(url(['document_file'=>$taxPreview['document']['id']])) ?>"><?= e($taxText('Unterlagenpaket herunterladen (ZIP)')) ?></a><a class="btn btn-outline theme-secondary button secondary" href="<?= e(url(['view'=>'documents','doc'=>$taxPreview['document']['id']])) ?>"><?= e($taxText('Paket in der Dokumentablage')) ?></a></div><?php else: ?><p class="notice"><strong><?= e($taxText('Vorschau · noch nicht gespeichert.')) ?></strong> <?= e($taxText('Prüfen Sie den folgenden Stand. Offene Angaben bleiben als offen gekennzeichnet.')) ?></p><?php endif ?>
<?= \Kulturhus\Verein\TaxPreparation::summaryHtml($taxPreview['snapshot'],$taxText) ?>
<?php if(!$taxSaved): ?><details><summary><?= e($taxText('Alle Dateien des Pakets ansehen')) ?></summary><p><?= e($taxText('Die lesbare Übersicht liegt zusätzlich als')) ?> <strong>uebersicht.html</strong> <?= e($taxText('im Paket. Journale und Kontenlisten sind als CSV enthalten; die übrigen Datenstände als JSON.')) ?></p><?php foreach($taxPreview['files'] as $name=>$bytes): if(str_starts_with($name,'unterlagen/')||$name==='uebersicht.html')continue; ?><details><summary><?= e($name) ?></summary><?php if(str_ends_with($name,'.pdf')): ?><p><?= e($taxText('Freigegebenes PDF im Unterlagenpaket enthalten.')) ?></p><?php else: ?><pre><?= e($bytes) ?></pre><?php endif ?></details><?php endforeach ?><h4><?= e($taxText('Originalnachweise')) ?></h4><?php foreach($taxPreview['snapshot']['sources'] as $source): ?><p><a href="<?= e(url(['document_file'=>$source['document_id'],'revision'=>(string)$source['revision']])) ?>"><?= e($source['title']) ?> <?=e($taxText('· genau diese Dokumentversion herunterladen'))?></a></p><?php endforeach ?></details>
<?php if(\Kulturhus\Verein\Permissions::actor($db,(string)$_SESSION['actor'])['finance_access']==='write'): ?><form method="post" action="<?=e(url(['view'=>'documents','tab'=>'activity-reports','report_kind'=>'tax']))?>"><?= csrf().hidden('prepare_token',\Kulturhus\Verein\Web\ActivityReportPrepareTicket::issue($db,(string)$_SESSION['actor'],'tax',$_SESSION)).hidden('action','activity-report-prepare').hidden('report_kind','tax').hidden('from_year',$taxPreview['snapshot']['from']).hidden('to_year',$taxPreview['snapshot']['to']).hidden('supplement',$taxPreview['snapshot']['activity']) ?><button class="btn btn-outline theme-secondary secondary"><?= e($taxText('Finanzamtsbericht zur Prüfung vorlegen')) ?></button></form><?php endif ?>

<?php $annualReceipt=$_SESSION['tax_previews'][$taxPreview['token']??'']??null;if(is_array($annualReceipt)&&is_string($annualReceipt['request_key']??null)):?><p><a class="btn btn-outline" data-annual-tax-read-first target="_blank" rel="noopener" href="<?=e(url($annualTaxRoute+['annual_tax_outcome'=>$annualReceipt['request_key']]))?>"><?=e($taxText('Gespeicherten Jahresausgang in neuem Tab lesen'))?></a></p><?php endif?>
<div class="tax-review-actions"><p><?= e($taxText('Beim Speichern wird kontrolliert, ob Buchungen, Eingaben und Anlagen noch dieser Vorschau entsprechen. Bei Änderungen ist eine neue Vorschau nötig.')) ?></p><p data-tax-preview-changed hidden class="tax-warning"><?= e($taxText('Sie haben Angaben geändert. Bitte oben erneut „Vollständige Vorschau erstellen“ wählen.')) ?></p><?php if((new \Kulturhus\Verein\Finance($db,(string)$_SESSION['actor']))->canWrite()):?><button class="btn btn-solid theme-primary" type="submit" form="tax-preparation-form" name="action" value="tax-bundle" data-tax-save><?= e($taxText('Diesen Vorbereitungsstand speichern')) ?></button><?php endif?><p><?= e($taxText('Speichert die Arbeitsunterlagen und offenen Punkte. Keine Steuerabgabe oder automatische Bestätigung ihrer Vollständigkeit.')) ?></p></div>
<?php else: ?><p><?= e($taxText('Die Originalnachweise liegen in den dokumentierten Versionen im ZIP. Spätere Änderungen an Stammdaten, Buchungen oder Dokumenten überschreiben dieses Paket nicht.')) ?></p><?php endif ?>
</section>
